1: // Fly control from the worker. The org admin token (env.FLY_API_TOKEN) never
2: // leaves this process; the CLI only ever receives 1h app-scoped deploy tokens.
3: // Chosen over building from a tarball here: Fly has no build-from-tarball REST
4: // endpoint — remote builds speak the Docker/BuildKit protocol to a builder
5: // machine, which a Worker cannot. See docs/v3.
6: const MACHINES = 'https://api.machines.dev/v1';
7: const GQL = 'https://api.fly.io/graphql';
8: 
9: // Two credentials: FLY_ORG_TOKEN (long-lived org token) for app/IP/machine ops,
10: // FLY_API_TOKEN (short-lived user token) only for minting limited tokens —
11: // Fly rejects createLimitedAccessToken from org tokens (verified both dashboard-
12: // and flyctl-created). ponytail: user token's discharge expires in <1h, so
13: // minting (and thus deploys) needs a fresh one; offline macaroon attenuation of
14: // the org token would remove that — v4.
15: const authH = (token) => (token.startsWith('FlyV1') ? token : `Bearer ${token}`);
16: const machineToken = (env) => env.FLY_ORG_TOKEN || env.FLY_API_TOKEN;
17: 
18: async function gql(token, query, variables) {
19:   const resp = await fetch(GQL, {
20:     method: 'POST',
21:     headers: { Authorization: authH(token), 'Content-Type': 'application/json' },
22:     body: JSON.stringify({ query, variables }),
23:   });
24:   const body = await resp.json();
25:   if (body.errors) throw new Error(`fly graphql: ${body.errors[0].message}`);
26:   return body.data;
27: }
28: 
29: // Create the Fly app + shared IPv4. Idempotent — rerun on every deploy.
30: export async function ensureFlyApp(env, flyApp) {
31:   const resp = await fetch(`${MACHINES}/apps`, {
32:     method: 'POST',
33:     headers: { Authorization: authH(machineToken(env)), 'Content-Type': 'application/json' },
34:     body: JSON.stringify({ app_name: flyApp, org_slug: env.FLY_ORG_SLUG || 'personal' }),
35:   });
36:   if (!resp.ok) {
37:     const text = await resp.text();
38:     if (!/taken|already/i.test(text)) throw new Error(`fly app create failed (${resp.status}): ${text}`);
39:   }
40:   await gql(machineToken(env), 'mutation($app: ID!) { allocateIpAddress(input: {appId: $app, type: shared_v4}) { app { name } } }', { app: flyApp });
41: }
42: 
43: let orgIdCache;
44: async function orgId(env) {
45:   if (env.FLY_ORG_ID) return env.FLY_ORG_ID; // pinned: skips a flaky orgs query on the aging user token
46:   if (!orgIdCache) {
47:     const { organizations } = await gql(env.FLY_API_TOKEN, 'query { organizations { nodes { id slug type } } }');
48:     const nodes = organizations.nodes.filter(Boolean);
49:     const slug = env.FLY_ORG_SLUG || 'personal';
50:     const node = nodes.find((n) => n.slug === slug) || nodes.find((n) => n.type === 'PERSONAL');
51:     if (!node) throw new Error(`no fly org matching ${slug}`);
52:     orgIdCache = node.id;
53:   }
54:   return orgIdCache;
55: }
56: 
57: // Start one machine for a job run. auto_destroy + restart "no": the machine
58: // runs the image's CMD to completion and Fly removes it.
59: export async function startMachine(env, flyApp, config) {
60:   const resp = await fetch(`${MACHINES}/apps/${flyApp}/machines`, {
61:     method: 'POST',
62:     headers: { Authorization: authH(machineToken(env)), 'Content-Type': 'application/json' },
63:     body: JSON.stringify({ config }),
64:   });
65:   if (!resp.ok) throw new Error(`fly machine start failed (${resp.status}): ${await resp.text()}`);
66:   return resp.json();
67: }
68: 
69: // The only Fly credential the CLI ever sees: deploy-scoped to one app.
70: // Minting requires the user token — org tokens get UNAUTHORIZED here — and user
71: // tokens' org authorization rots ~30min after `flyctl auth token`. So each app's
72: // token is minted ONCE at app creation (30 days) and stored in D1; deploys of
73: // existing apps never touch the user token again. ponytail: stored token = one
74: // app's creds at rest for 30d; offline macaroon attenuation of the org token
75: // (superfly/macaroon has no JS port yet) replaces this in v4.
76: export async function mintDeployToken(env, flyApp) {
77:   const data = await gql(
78:     env.FLY_API_TOKEN,
79:     'mutation($input: CreateLimitedAccessTokenInput!) { createLimitedAccessToken(input: $input) { limitedAccessToken { tokenHeader } } }',
80:     { input: { name: `small-${flyApp}`, organizationId: await orgId(env), profile: 'deploy', profileParams: { app_id: flyApp }, expiry: '720h0m0s' } }
81:   );
82:   return data.createLimitedAccessToken.limitedAccessToken.tokenHeader;
83: }
84: 
85: // Stored-token accessor: serve from D1, mint+store on miss.
86: export async function deployTokenFor(env, app) {
87:   if (app.deploy_token) return app.deploy_token;
88:   const token = await mintDeployToken(env, app.fly_app);
89:   await env.DB.prepare('UPDATE apps SET deploy_token = ? WHERE id = ?').bind(token, app.id).run();
90:   return token;
91: }

sources.packages/control-plane/src/index.js:
1: // small control plane: CLI API + browser auth wall + router. One Worker + D1.
2: // URLs are path-based (no custom domain): /a/<org>/<app>/... proxies to the app's Fly origin.
3: import { sign, verify, sha256, randomHex } from './token.js';
4: import { ensureFlyApp, deployTokenFor, startMachine } from './fly.js';
5: import { assumeRole } from './aws.js';
6: import { runReview } from './review.js';
7: 
8: const SESSION_COOKIE = 'small_session';
9: const SESSION_TTL = 7 * 24 * 3600;
10: 
11: const orgOf = (email) => email.split('@')[1].toLowerCase().replace(/\./g, '-');
12: const now = () => Math.floor(Date.now() / 1000);
13: const json = (data, status = 200) => new Response(JSON.stringify(data), { status, headers: { 'Content-Type': 'application/json' } });
14: const html = (body, status = 200, headers = {}) =>
15:   new Response(`<!doctype html><meta name=viewport content="width=device-width,initial-scale=1"><style>body{font-family:system-ui;max-width:26rem;margin:15vh auto;padding:0 1rem}input,button{font-size:1rem;padding:.5rem}</style>${body}`, {
16:     status,
17:     headers: { 'Content-Type': 'text/html;charset=utf-8', ...headers },
18:   });
19: 
20: async function sendEmail(env, to, subject, text) {
21:   if (!env.RESEND_API_KEY) return false; // dev mode: caller falls back to echoing the code/link
22:   const resp = await fetch('https://api.resend.com/emails', {
23:     method: 'POST',
24:     headers: { Authorization: `Bearer ${env.RESEND_API_KEY}`, 'Content-Type': 'application/json' },
25:     body: JSON.stringify({ from: env.EMAIL_FROM || 'small <[REDACTED]>', to: [to], subject, text }),
26:   });
27:   return resp.ok;
28: }
29: 
30: async function cliAuth(req, env) {
31:   const m = (req.headers.get('Authorization') || '').match(/^Bearer (.+)$/);
32:   if (!m) return null;
33:   const p = await verify(m[1], env.MASTER_KEY);
34:   return p && p.t === 'cli' ? p : null;
35: }
36: 
37: async function sessionOf(req, env) {
38:   const header = req.headers.get('X-Small-Session'); // tests use the header; browsers use the cookie
39:   const cookie = (req.headers.get('Cookie') || '').match(new RegExp(`${SESSION_COOKIE}=([^;]+)`));
40:   const p = await verify(header || (cookie && cookie[1]), env.MASTER_KEY);
41:   return p && p.t === 'sess' ? p : null;
42: }
43: 
44: async function appRow(env, org, name) {
45:   return env.DB.prepare('SELECT * FROM apps WHERE org = ? AND name = ?').bind(org, name).first();
46: }
47: 
48: async function canView(env, app, email) {
49:   if (app.owner_email === email) return true;
50:   const member = await env.DB.prepare('SELECT role FROM members WHERE app_id = ? AND email = ?').bind(app.id, email).first();
51:   if (member) return true;
52:   return app.visibility === 'domain' && orgOf(email) === app.org;
53: }
54: 
55: async function canEdit(env, app, email) {
56:   if (app.owner_email === email) return true;
57:   const member = await env.DB.prepare('SELECT role FROM members WHERE app_id = ? AND email = ?').bind(app.id, email).first();
58:   return member && member.role === 'edit';
59: }
60: 
61: // ---------- CLI API ----------
62: 
63: async function apiLogin(req, env) {
64:   const { email } = await req.json();
65:   if (!email || !email.includes('@')) return json({ error: 'valid email required' }, 400);
66:   const code = String(crypto.getRandomValues(new Uint32Array(1))[0] % 1000000).padStart(6, '0');
67:   const challenge = await sign({ t: 'challenge', email, codeHash: await sha256(code), exp: now() + 600 }, env.MASTER_KEY);
68:   const sent = await sendEmail(env, email, `small login code: ${code}`, `Your small login code is ${code}\nIt expires in 10 minutes.`);
69:   if (sent) return json({ challenge });
70:   // Echoing the code is an auth bypass — only allowed on test/dev instances (marked by TEST_BYPASS_SECRET).
71:   if (!env.TEST_BYPASS_SECRET) return json({ error: 'email not configured on this control plane' }, 503);
72:   return json({ challenge, devCode: code, warning: 'test instance — code echoed' });
73: }
74: 
75: async function apiVerify(req, env) {
76:   const { challenge, code } = await req.json();
77:   const p = await verify(challenge, env.MASTER_KEY);
78:   if (!p || p.t !== 'challenge' || p.codeHash !== (await sha256(String(code)))) return json({ error: 'bad or expired code' }, 401);
79:   // ponytail: CLI tokens never expire; revoke by rotating MASTER_KEY. Add exp + refresh when it matters.
80:   const token = await sign({ t: 'cli', email: p.email, org: orgOf(p.email) }, env.MASTER_KEY);
81:   return json({ token, email: p.email, org: orgOf(p.email) });
82: }
83: 
84: async function apiDeploy(req, env, ctx, user, baseUrl) {
85:   const { name, framework, visibility, awsRoleArn, kind, review } = await req.json();
86:   if (!name || !/^[a-z0-9-]{1,40}$/.test(name)) return json({ error: 'name must be [a-z0-9-]' }, 400);
87:   if (awsRoleArn && !/^arn:aws:iam::\d{12}:role\/[\w+=,.@/-]+$/.test(awsRoleArn)) return json({ error: 'bad aws role arn' }, 400);
88:   let app = await appRow(env, user.org, name);
89:   if (app) {
90:     if (!(await canEdit(env, app, user.email))) return json({ error: `${name} exists and you cannot edit it` }, 403);
91:     if (visibility) await env.DB.prepare('UPDATE apps SET visibility = ? WHERE id = ?').bind(visibility, app.id).run();
92:     if (awsRoleArn !== undefined) await env.DB.prepare('UPDATE apps SET aws_role_arn = ? WHERE id = ?').bind(awsRoleArn || null, app.id).run();
93:     if (kind) await env.DB.prepare('UPDATE apps SET kind = ? WHERE id = ?').bind(kind === 'job' ? 'job' : 'server', app.id).run();
94:   } else {
95:     const flyApp = `small-${name}-${randomHex(3)}`;
96:     await env.DB.prepare('INSERT INTO apps (org, name, fly_app, proxy_secret, visibility, owner_email, aws_role_arn, kind) VALUES (?, ?, ?, ?, ?, ?, ?, ?)')
97:       .bind(user.org, name, flyApp, randomHex(32), visibility || 'domain', user.email, awsRoleArn || null, kind === 'job' ? 'job' : 'server')
98:       .run();
99:     app = await appRow(env, user.org, name);
100:   }
101:   if (!env.FLY_API_TOKEN) return json({ error: 'control plane has no FLY_API_TOKEN configured' }, 503);
102:   // The worker owns the Fly app lifecycle; the CLI only gets a 1h token scoped to this one app.
103:   let flyToken;
104:   try {
105:     await ensureFlyApp(env, app.fly_app);
106:     flyToken = await deployTokenFor(env, app);
107:   } catch (e) {
108:     return json({ error: e.message }, 502);
109:   }
110:   // Review runs concurrently with the CLI-side Fly build; it never blocks or fails the deploy.
111:   const reviewStarted = !!(env.ANTHROPIC_API_KEY && review && review.bundle);
112:   if (reviewStarted) ctx.waitUntil(runReview(env, app.id, review.bundle, review.skipped || []));
113:   return json({
114:     flyApp: app.fly_app,
115:     proxySecret: app.proxy_secret,
116:     flyToken,
117:     url: `${baseUrl}/a/${user.org}/${name}/`,
118:     framework: framework || null,
119:     reviewStarted,
120:     reviewedAt: app.reviewed_at || null, // previous review's stamp; the CLI polls until it changes
121:   });
122: }
123: 
124: async function apiReview(req, env, user) {
125:   const name = new URL(req.url).searchParams.get('app');
126:   const app = await appRow(env, user.org, name);
127:   if (!app) return json({ error: `no app named ${name}` }, 404);
128:   if (!(await canView(env, app, user.email))) return json({ error: 'no access' }, 403);
129:   return json({
130:     review: app.review ? JSON.parse(app.review) : null,
131:     prev: app.review_prev ? JSON.parse(app.review_prev) : null,
132:     reviewedAt: app.reviewed_at || null,
133:     model: app.review_model || null,
134:   });
135: }
136: 
137: async function apiShare(req, env, user) {
138:   const { app: name, email, role } = await req.json();
139:   const app = await appRow(env, user.org, name);
140:   if (!app) return json({ error: `no app named ${name}` }, 404);
141:   if (!(await canEdit(env, app, user.email))) return json({ error: 'only owner or edit members can share' }, 403);
142:   await env.DB.prepare('INSERT INTO members (app_id, email, role) VALUES (?, ?, ?) ON CONFLICT(app_id, email) DO UPDATE SET role = excluded.role')
143:     .bind(app.id, email.toLowerCase(), role === 'edit' ? 'edit' : 'view')
144:     .run();
145:   return json({ ok: true, app: name, email: email.toLowerCase(), role: role === 'edit' ? 'edit' : 'view' });
146: }
147: 
148: async function apiApps(env, user) {
149:   const { results } = await env.DB.prepare('SELECT name, visibility, owner_email, fly_app, created_at FROM apps WHERE org = ? ORDER BY name').bind(user.org).all();
150:   return json({ apps: results });
151: }
152: 
153: async function apiLogs(req, env, user) {
154:   const name = new URL(req.url).searchParams.get('app');
155:   const app = await appRow(env, user.org, name);
156:   if (!app) return json({ error: `no app named ${name}` }, 404);
157:   if (!(await canView(env, app, user.email))) return json({ error: 'no access' }, 403);
158:   if (!env.FLY_API_TOKEN) return json({ error: 'control plane has no FLY_API_TOKEN configured' }, 503);
159:   try {
160:     return json({ flyApp: app.fly_app, flyToken: await deployTokenFor(env, app) });
161:   } catch (e) {
162:     return json({ error: e.message }, 502);
163:   }
164: }
165: 
166: // Runtime endpoint: the guard inside a machine trades its proxy secret for 1h STS
167: // session creds scoped by the customer's role. No CLI token involved — the proxy
168: // secret is per-app and high-entropy. ExternalId pins the role to the app's org so
169: // one org cannot point small.toml at another org's role (confused deputy).
170: async function apiAwsCreds(req, env) {
171:   const { secret } = await req.json();
172:   if (!secret) return json({ error: 'secret required' }, 400);
173:   const app = await env.DB.prepare('SELECT * FROM apps WHERE proxy_secret = ?').bind(secret).first();
174:   if (!app) return json({ error: 'forbidden' }, 403);
175:   if (!app.aws_role_arn) return json({ error: 'no aws role configured for this app' }, 404);
176:   if (!env.AWS_ACCESS_KEY_ID || !env.AWS_SECRET_ACCESS_KEY) return json({ error: 'control plane has no AWS principal configured' }, 503);
177:   try {
178:     return json(await assumeRole(env, app.aws_role_arn, `small-${app.org}-${app.name}`, app.org));
179:   } catch (e) {
180:     return json({ error: e.message }, 502);
181:   }
182: }
183: 
184: // ---------- Job runs ----------
185: 
186: // Registered by the CLI after `fly deploy --build-only --push` — jobs deploy an image, not machines.
187: async function apiImage(req, env, user) {
188:   const { app: name, image } = await req.json();
189:   const app = await appRow(env, user.org, name);
190:   if (!app) return json({ error: `no app named ${name}` }, 404);
191:   if (!(await canEdit(env, app, user.email))) return json({ error: 'no access' }, 403);
192:   if (!/^registry\.fly\.io\/[\w./:-]+$/.test(image || '')) return json({ error: 'bad image ref' }, 400);
193:   await env.DB.prepare('UPDATE apps SET image = ? WHERE id = ?').bind(image, app.id).run();
194:   return json({ ok: true });
195: }
196: 
197: async function apiRunStart(req, env, user, baseUrl) {
198:   const { app: name } = await req.json();
199:   const app = await appRow(env, user.org, name);
200:   if (!app) return json({ error: `no app named ${name}` }, 404);
201:   if (!(await canView(env, app, user.email))) return json({ error: 'no access' }, 403);
202:   if (app.kind !== 'job') return json({ error: `${name} is not a job — set kind = "job" in small.toml and redeploy` }, 400);
203:   if (!app.image) return json({ error: `no image for ${name} — run small deploy first` }, 409);
204:   if (!env.FLY_ORG_TOKEN && !env.FLY_API_TOKEN) return json({ error: 'control plane has no fly token configured' }, 503);
205:   const runId = 'r-' + randomHex(6);
206:   await env.DB.prepare('INSERT INTO runs (run_id, app_id, started_by) VALUES (?, ?, ?)').bind(runId, app.id, user.email).run();
207:   const runToken = await sign({ t: 'run', run: runId, exp: now() + 6 * 3600 }, env.MASTER_KEY);
208:   try {
209:     await startMachine(env, app.fly_app, {
210:       image: app.image,
211:       auto_destroy: true,
212:       restart: { policy: 'no' },
213:       guest: { cpu_kind: 'shared', cpus: 1, memory_mb: 256 }, // ponytail: fixed size; read memory from small.toml when a job needs more
214:       env: { SMALL_RUN_ID: runId, SMALL_RUN_TOKEN: runToken, SMALL_USER: user.email, SMALL_API: baseUrl },
215:     });
216:   } catch (e) {
217:     await env.DB.prepare("UPDATE runs SET status = 'failed', finished_at = datetime('now') WHERE run_id = ?").bind(runId).run();
218:     return json({ error: e.message }, 502);
219:   }
220:   return json({ runId });
221: }
222: 
223: async function apiRunsList(req, env, user) {
224:   const name = new URL(req.url).searchParams.get('app');
225:   const app = await appRow(env, user.org, name);
226:   if (!app) return json({ error: `no app named ${name}` }, 404);
227:   if (!(await canView(env, app, user.email))) return json({ error: 'no access' }, 403);
228:   const { results } = await env.DB.prepare(
229:     'SELECT run_id, status, exit_code, started_by, started_at, finished_at FROM runs WHERE app_id = ? ORDER BY id DESC'
230:   ).bind(app.id).all();
231:   return json({ runs: results });
232: }
233: 
234: async function apiRunGet(req, env, user, runId) {
235:   const run = await env.DB.prepare(
236:     'SELECT runs.status, runs.exit_code, apps.id AS app_id, apps.org, apps.owner_email, apps.visibility FROM runs JOIN apps ON apps.id = runs.app_id WHERE runs.run_id = ?'
237:   ).bind(runId).first();
238:   if (!run || run.org !== user.org) return json({ error: `no run ${runId}` }, 404);
239:   if (!(await canView(env, { id: run.app_id, org: run.org, owner_email: run.owner_email, visibility: run.visibility }, user.email)))
240:     return json({ error: 'no access' }, 403);
241:   const after = Number(new URL(req.url).searchParams.get('after') ?? -1);
242:   const { results } = await env.DB.prepare('SELECT seq, line FROM run_logs WHERE run_id = ? AND seq > ? ORDER BY seq').bind(runId, after).all();
243:   return json({
244:     status: run.status,
245:     exitCode: run.exit_code,
246:     lines: results.map((r) => r.line),
247:     cursor: results.length ? results[results.length - 1].seq : after,
248:   });
249: }
250: 
251: // Called by runner.py with the per-run token — not a CLI token.
252: async function apiRunLog(req, env, runId) {
253:   const m = (req.headers.get('Authorization') || '').match(/^Bearer (.+)$/);
254:   const p = m && (await verify(m[1], env.MASTER_KEY));
255:   if (!p || p.t !== 'run' || p.run !== runId) return json({ error: 'bad run token' }, 401);
256:   const { lines = [], exitCode } = await req.json();
257:   if (lines.length) {
258:     // ponytail: MAX(seq) is race-free only because one runner posts batches sequentially
259:     const { m: maxSeq } = await env.DB.prepare('SELECT COALESCE(MAX(seq), -1) AS m FROM run_logs WHERE run_id = ?').bind(runId).first();
260:     let seq = maxSeq;
261:     const stmt = env.DB.prepare('INSERT INTO run_logs (run_id, seq, line) VALUES (?, ?, ?)');
262:     await env.DB.batch(lines.map((l) => stmt.bind(runId, ++seq, String(l))));
263:   }
264:   if (exitCode !== undefined && exitCode !== null) {
265:     await env.DB.prepare("UPDATE runs SET status = ?, exit_code = ?, finished_at = datetime('now') WHERE run_id = ?")
266:       .bind(exitCode === 0 ? 'finished' : 'failed', exitCode, runId)
267:       .run();
268:   }
269:   return json({ ok: true });
270: }
271: 
272: // ---------- Browser wall ----------
273: 
274: function sessionCookie(token) {
275:   return `${SESSION_COOKIE}=${token}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=${SESSION_TTL}`;
276: }
277: 
278: async function loginPage(req, env, baseUrl) {
279:   const url = new URL(req.url);
280:   const next = url.searchParams.get('next') || '/';
281:   if (req.method === 'POST') {
282:     const form = await req.formData();
283:     const email = String(form.get('email') || '').toLowerCase().trim();
284:     if (!email.includes('@')) return html('<p>Enter a valid work email.</p><a href="javascript:history.back()">back</a>', 400);
285:     const magic = await sign({ t: 'magic', email, next, exp: now() + 900 }, env.MASTER_KEY);
286:     const link = `${baseUrl}/auth?token=${encodeURIComponent(magic)}`;
287:     const sent = await sendEmail(env, email, 'Your small sign-in link', `Sign in: ${link}\nExpires in 15 minutes.`);
288:     if (sent) return html(`<h2>Check your inbox</h2><p>We sent a sign-in link to <b>${email}</b>.</p>`);
289:     if (!env.TEST_BYPASS_SECRET) return html('<p>Email is not configured on this control plane.</p>', 503);
290:     return html(`<h2>Test instance</h2><p>Dev sign-in link:</p><p><a href="${link}">${link}</a></p>`);
291:   }
292:   return html(`<h2>Sign in to small</h2><form method=post><input name=email type=email placeholder=[REDACTED] required autofocus> <button>Send link</button></form>`);
293: }
294: 
295: async function authRedirect(req, env) {
296:   const token = new URL(req.url).searchParams.get('token');
297:   const p = await verify(token, env.MASTER_KEY);
298:   if (!p || p.t !== 'magic') return html('<p>Link expired or invalid. <a href="/login">Try again</a>.</p>', 401);
299:   const sess = await sign({ t: 'sess', email: p.email, exp: now() + SESSION_TTL }, env.MASTER_KEY);
300:   return new Response(null, { status: 302, headers: { Location: p.next || '/', 'Set-Cookie': sessionCookie(sess) } });
301: }
302: 
303: // Test bypass: mint a session without email. Enabled only when TEST_BYPASS_SECRET is set.
304: async function testSession(req, env) {
305:   if (!env.TEST_BYPASS_SECRET) return json({ error: 'not enabled' }, 404);
306:   const { email, secret } = await req.json();
307:   if (secret !== env.TEST_BYPASS_SECRET) return json({ error: 'bad secret' }, 401);
308:   const sess = await sign({ t: 'sess', email: email.toLowerCase(), exp: now() + SESSION_TTL }, env.MASTER_KEY);
309:   return json({ session: sess }, 200);
310: }
311: 
312: // ---------- Router/proxy ----------
313: 
314: async function proxyApp(req, env, org, name, rest, baseUrl) {
315:   const sess = await sessionOf(req, env);
316:   const prefix = `/a/${org}/${name}`;
317:   if (!sess) {
318:     if (req.method !== 'GET') return json({ error: 'login required' }, 401);
319:     return new Response(null, { status: 302, headers: { Location: `${baseUrl}/login?next=${encodeURIComponent(prefix + '/')}` } });
320:   }
321:   const app = await appRow(env, org, name);
322:   if (!app) return html(`<p>No app <b>${name}</b> here.</p>`, 404);
323:   if (!(await canView(env, app, sess.email))) return html(`<p><b>${sess.email}</b> does not have access to <b>${name}</b>. Ask the owner to run <code>small share ${sess.email}</code>.</p>`, 403);
324:   if (rest === '') return new Response(null, { status: 301, headers: { Location: `${prefix}/` } }); // relative URLs need the trailing slash
325: 
326:   const origin = `https://${app.fly_app}.fly.dev`;
327:   const target = new URL(req.url);
328:   const headers = new Headers(req.headers);
329:   headers.delete('Cookie'); // the app never sees the session
330:   headers.delete('X-Small-Session');
331:   headers.set('X-Small-User', sess.email);
332:   headers.set('X-Small-Org', org);
333:   headers.set('X-Small-Proxy', app.proxy_secret);
334:   let resp;
335:   for (let attempt = 0; ; attempt++) {
336:     resp = await fetch(`${origin}${rest}${target.search}`, {
337:       method: req.method,
338:       headers,
339:       body: ['GET', 'HEAD'].includes(req.method) ? undefined : req.body,
340:       redirect: 'manual',
341:     });
342:     // Fly answers 502/503 while a scaled-to-zero machine wakes (~30s for torch-heavy apps);
343:     // hold safe-to-repeat requests instead of showing the browser a Bad Gateway.
344:     if (![502, 503].includes(resp.status) || !['GET', 'HEAD'].includes(req.method) || attempt >= 9) break;
345:     await new Promise((r) => setTimeout(r, 5000));
346:   }
347:   const out = new Headers(resp.headers);
348:   const loc = out.get('Location');
349:   if (loc && loc.startsWith('/') && !loc.startsWith('/a/')) out.set('Location', prefix + loc); // path-based hosting: re-prefix app redirects
350:   return new Response(resp.body, { status: resp.status, headers: out });
351: }
352: 
353: export default {
354:   async fetch(req, env, ctx) {
355:     const url = new URL(req.url);
356:     const baseUrl = `${url.protocol}//${url.host}`;
357:     const path = url.pathname;
358:     try {
359:       if (path === '/api/cli/login' && req.method === 'POST') return await apiLogin(req, env);
360:       if (path === '/api/cli/verify' && req.method === 'POST') return await apiVerify(req, env);
361:       if (path === '/api/runtime/aws-creds' && req.method === 'POST') return await apiAwsCreds(req, env);
362:       if (path.startsWith('/api/')) {
363:         const runLog = path.match(/^\/api\/runs\/([\w-]+)\/log$/);
364:         if (runLog && req.method === 'POST') return await apiRunLog(req, env, runLog[1]); // runner auth, not CLI auth
365:         const user = await cliAuth(req, env);
366:         if (!user) return json({ error: 'run small login first' }, 401);
367:         if (path === '/api/deploy' && req.method === 'POST') return await apiDeploy(req, env, ctx, user, baseUrl);
368:         if (path === '/api/image' && req.method === 'POST') return await apiImage(req, env, user);
369:         if (path === '/api/runs' && req.method === 'POST') return await apiRunStart(req, env, user, baseUrl);
370:         if (path === '/api/runs' && req.method === 'GET') return await apiRunsList(req, env, user);
371:         const runGet = path.match(/^\/api\/runs\/([\w-]+)$/);
372:         if (runGet && req.method === 'GET') return await apiRunGet(req, env, user, runGet[1]);
373:         if (path === '/api/share' && req.method === 'POST') return await apiShare(req, env, user);
374:         if (path === '/api/apps' && req.method === 'GET') return await apiApps(env, user);
375:         if (path === '/api/logs' && req.method === 'GET') return await apiLogs(req, env, user);
376:         if (path === '/api/review' && req.method === 'GET') return await apiReview(req, env, user);
377:         return json({ error: 'no such endpoint' }, 404);
378:       }
379:       if (path === '/login') return await loginPage(req, env, baseUrl);
380:       if (path === '/auth') return await authRedirect(req, env);
381:       if (path === '/test/session' && req.method === 'POST') return await testSession(req, env);
382:       const m = path.match(/^\/a\/([a-z0-9-]+)\/([a-z0-9-]+)(\/.*)?$/);
383:       if (m) return await proxyApp(req, env, m[1], m[2], m[3] || '', baseUrl);
384:       if (path === '/') return html('<h2>small</h2><p>Deploy a Python app behind a login in one command: <code>npm i -g small-deploy</code></p>');
385:       return html('<p>Not found.</p>', 404);
386:     } catch (err) {
387:       return json({ error: `internal: ${err.message}` }, 500);
388:     }
389:   },
390: };

