15: const [cmd, ...rest] = process.argv.slice(2);
16: const flags = { _: [] };
17: for (let i = 0; i < rest.length; i++) {
18:   if (rest[i].startsWith('--')) {
19:     const key = rest[i].slice(2);
20:     flags[key] = rest[i + 1] && !rest[i + 1].startsWith('--') ? rest[++i] : true;
21:   } else {
22:     flags._.push(rest[i]);
23:   }
24: }
