118: const commands = {
119:   async login() {
120:     if (flags.api) config.save({ ...config.load(), apiBase: flags.api });
121:     const email = flags.email || (await ask('work email: '));
122:     const res = await call('POST', '/api/cli/login', { email }, { auth: false });
123:     if (res.devCode) console.log(`(dev) code: ${res.devCode}`);
124:     else console.log(`✓ code sent to ${email}`);
125:     const code = flags.code || (await ask('6-digit code: '));
126:     const v = await call('POST', '/api/cli/verify', { challenge: res.challenge, code }, { auth: false });
127:     config.save({ ...config.load(), token: v.token, email: v.email, org: v.org, apiBase: apiBase() });
128:     console.log(`✓ logged in as ${v.email} (org: ${v.org})`);
129:   },
130: 
131:   async init() {
132:     if (!init(process.cwd(), { force: !!flags.force })) process.exitCode = 1;
133:   },
134: 
135:   async deploy() {
136:     const dir = process.cwd();
137:     if (!fs.existsSync(path.join(dir, 'small.toml')) && !init(dir)) {
138:       process.exitCode = 1;
139:       return;
140:     }
141:     const app = detect(dir, flags);
142:     console.log(`✓ entry: ${app.entry} (${app.framework}) via ${app.via}`);
143: 
144:     const envPath = path.resolve(dir, typeof flags.env === 'string' ? flags.env : '.env');
145:     const secrets = envfile.parse(envPath);
146:     const required = (app.config.secrets && app.config.secrets.required) || [];
147:     const missing = required.filter((k) => !(k in secrets));
148:     if (missing.length) throw new Error(`missing secrets: ${missing.join(', ')} — add them to ${envPath}`);
149: 
150:     write(dir, app);
151:     const review = buildBundle(dir, app.entry, secrets);
152:     const visibility = (app.config.access && app.config.access.visibility) || undefined;
153:     const awsRoleArn = (app.config.aws && app.config.aws.role_arn) || undefined;
154:     const kind = app.config.kind === 'job' ? 'job' : 'server';
155:     const d = await call('POST', '/api/deploy', { name: app.name, framework: app.framework, visibility, awsRoleArn, kind, review });
156:     if (!d.flyToken) throw new Error('control plane has no FLY_API_TOKEN configured');
157:     writeFlyToml(dir, d.flyApp, app.config.memory);
158: 
159:     if (kind === 'job') {
160:       // jobs: build + register the image, start nothing — the control plane starts machines per run
161:       fly.setSecrets(d.flyApp, d.flyToken, secrets);
162:       const image = fly.buildImage(d.flyApp, d.flyToken, dir, `v${Date.now()}`);
163:       await call('POST', '/api/image', { app: app.name, image });
164:       console.log(`✓ built ${app.name} — start it with: small run ${app.name}`);
165:       return;
166:     }
167: 
168:     // gradio builds asset/API URLs from its root; behind the path proxy that must be the public URL
169:     const rootPath = app.framework === 'gradio' ? { GRADIO_ROOT_PATH: d.url.replace(/\/$/, '') } : {};
170:     // [aws] role: guard fetches STS session creds from the control plane at boot
171:     const cpUrl = awsRoleArn ? { SMALL_CP_URL: apiBase() } : {};
172:     fly.setSecrets(d.flyApp, d.flyToken, { SMALL_PROXY_SECRET: d.proxySecret, ...rootPath, ...cpUrl, ...secrets });
173:     if (awsRoleArn) console.log(`✓ aws role: ${awsRoleArn} (STS via control plane)`);
174:     fly.deploy(d.flyApp, d.flyToken, dir);
175: 
176:     console.log(`✓ deployed → ${d.url}`);
177:     const { org } = config.load();
178:     console.log(visibility === 'private' ? '✓ login required · explicit members only' : `✓ login required · anyone @${org}`);
179:     if (d.reviewStarted) await reviewAfterDeploy(app.name, d.reviewedAt);
180:     else console.log('review: unavailable');
181:   },
182: 
183:   async review() {
184:     const name = flags._[0] || appName(process.cwd());
185:     const res = await call('GET', `/api/review?app=${encodeURIComponent(name)}`);
186:     if (!res.review) return console.log('review: unavailable — no reviewed deploy yet');
187:     if (flags.diff) printDiff(res);
188:     else printReport(res);
189:   },
190: 
191:   async run() {
192:     const name = flags._[0] || appName(process.cwd());
193:     const { runId } = await call('POST', '/api/runs', { app: name });
194:     console.log(`run: ${runId}`);
195:     let cursor = -1;
196:     for (;;) {
197:       const r = await call('GET', `/api/runs/${encodeURIComponent(runId)}?after=${cursor}`);
198:       for (const line of r.lines) console.log(line);
199:       if (r.lines.length) cursor = r.cursor;
200:       if (r.status !== 'running' && !r.lines.length) {
201:         console.log(r.exitCode === 0 ? `✓ finished (exit ${r.exitCode})` : `✗ failed (exit ${r.exitCode})`);
202:         process.exitCode = r.exitCode === 0 ? 0 : 1;
203:         return;
204:       }
205:       await new Promise((res) => setTimeout(res, 1000));
206:     }
207:   },
208: 
209:   async runs() {
210:     const name = flags._[0] || appName(process.cwd());
211:     const { runs } = await call('GET', `/api/runs?app=${encodeURIComponent(name)}`);
212:     if (!runs.length) return console.log(`no runs yet — small run ${name}`);
213:     for (const r of runs) {
214:       // sqlite datetime('now') strings are UTC without a zone marker
215:       const dur = r.finished_at ? `${Math.round((new Date(r.finished_at + 'Z') - new Date(r.started_at + 'Z')) / 1000)}s` : '…';
216:       console.log(`${r.run_id}  ${r.status}  ${dur}  ${r.started_by}  ${r.started_at}`);
217:     }
218:   },
219: 
220:   async logs() {
221:     const arg = flags._[0];
222:     if (arg && arg.startsWith('r-')) {
223:       const r = await call('GET', `/api/runs/${encodeURIComponent(arg)}?after=-1`);
224:       for (const line of r.lines) console.log(line);
225:       return;
226:     }
227:     const name = arg || appName(process.cwd());
228:     const res = await call('GET', `/api/logs?app=${encodeURIComponent(name)}`);
229:     if (!res.flyToken) throw new Error('control plane has no FLY_API_TOKEN configured');
230:     fly.logs(res.flyApp, res.flyToken);
231:   },
232: 
233:   async share() {
234:     const email = flags._[0];
235:     if (!email || !email.includes('@')) throw new Error('usage: small share <email> [--edit] [--app name]');
236:     const name = appName(process.cwd());
237:     const res = await call('POST', '/api/share', { app: name, email, role: flags.edit ? 'edit' : 'view' });
238:     console.log(`✓ ${res.email} can ${res.role} ${res.app}`);
239:   },
240: 
241:   async list() {
242:     const { apps } = await call('GET', '/api/apps');
243:     if (!apps.length) return console.log('no apps yet — run small deploy');
244:     for (const a of apps) console.log(`${a.name}  ${a.visibility}  owner:${a.owner_email}`);
245:   },
246: 
247: };
