249: const run = commands[cmd];
250: if (!run) {
251:   console.log('usage: small <login|init|deploy|run|runs|share|list|logs|review>');
252:   process.exitCode = 1;
253: } else {
254:   run().catch((err) => {
255:     console.error(`✗ ${err.message}`);
256:     process.exitCode = 1;
257:   });
258: }
